    Bug 2008907 - Migrate persisted checked attribute values. r=aleca

    Differential Revision: https://phabricator.services.mozilla.com/D278231

diff --git a/mail/modules/MailMigrator.sys.mjs b/mail/modules/MailMigrator.sys.mjs
index 926cf84c0b2..7886717de25 100644
--- a/mail/modules/MailMigrator.sys.mjs
+++ b/mail/modules/MailMigrator.sys.mjs
@@ -30,7 +30,7 @@ export var MailMigrator = {
   _migrateUI() {
     // The code for this was ported from
     // mozilla/browser/components/nsBrowserGlue.js
-    const UI_VERSION = 56;
+    const UI_VERSION = 57;
     const UI_VERSION_PREF = "mail.ui-rdf.version";
     let currentUIVersion = Services.prefs.getIntPref(UI_VERSION_PREF, 0);

@@ -375,6 +375,45 @@ export var MailMigrator = {
         Services.prefs.clearUserPref("experimental.mail.ews.enabled");
       }

+      if (currentUIVersion < 57) {
+        function updateValue(url, id) {
+          if (Services.xulStore.hasValue(url, id, "checked")) {
+            const oldValue = Services.xulStore.getValue(url, id, "checked");
+            Services.xulStore.setValue(
+              url,
+              id,
+              "checked",
+              oldValue == "false" ? "-moz-missing\n" : ""
+            );
+          }
+        }
+
+        updateValue(
+          "chrome://calendar/content/calendar-event-dialog.xhtml",
+          "cmd_timezone"
+        );
+        updateValue(
+          "chrome://calendar/content/calendar-item-panel.inc.xhtml",
+          "cmd_timezone"
+        );
+        updateValue(
+          "chrome://messenger/content/SearchDialog.xhtml",
+          "checkSearchSubFolders"
+        );
+        updateValue(
+          "chrome://messenger/content/messengercompose/EdConvertToTable.xhtml",
+          "CollapseSpaces"
+        );
+        updateValue(
+          "chrome://openpgp/content/ui/enigmailKeyManager.xhtml",
+          "showInvalidKeys"
+        );
+        updateValue(
+          "chrome://openpgp/content/ui/enigmailKeyManager.xhtml",
+          "showOthersKeys"
+        );
+      }
+
       // Migration tasks that may take a long time are not run immediately, but
       // added to the MigrationTasks object then run at the end.
       //
